class Solution {
public:
    int findColoredRoot(vector<vector<int>>& edges, string colors) {
        int n = colors.size();
        // adjacency list: neighbour, flag (1 = forced current->neighbour, -1 = opposite)
        vector<vector<pair<int,int>>> g(n);
        auto succ = [&](char c) -> char {
            if (c == 'R') return 'B';
            if (c == 'B') return 'W';
            return 'R';
        };
        for (auto &e : edges) {
            int u = e[0], v = e[1];
            if (colors[u] == colors[v]) return -1;               // impossible edge
            if (colors[v] == succ(colors[u])) {
                g[u].push_back({v, 1});
                g[v].push_back({u, -1});
            } else {
                g[u].push_back({v, -1});
                g[v].push_back({u, 1});
            }
        }

        vector<int> bad(n, 0);
        int bad0 = 0;
        function<void(int,int)> dfs1 = [&](int u, int p) {
            for (auto &pr : g[u]) {
                int v = pr.first, dir = pr.second;
                if (v == p) continue;
                if (dir == -1) ++bad0;          // edge oriented opposite to forced direction
                dfs1(v, u);
            }
        };
        dfs1(0, -1);
        bad[0] = bad0;

        function<void(int,int)> dfs2 = [&](int u, int p) {
            for (auto &pr : g[u]) {
                int v = pr.first, dir = pr.second;
                if (v == p) continue;
                // moving root from u to v flips this edge
                bad[v] = bad[u] + (dir == 1 ? 1 : -1);
                dfs2(v, u);
            }
        };
        dfs2(0, -1);

        for (int i = 0; i < n; ++i) {
            if (bad[i] == 0 && (int)g[i].size() <= 2) return i;
        }
        return -1;
    }
};
